      </div>

      <!-- Empty state -->
      <div
        v-if="!tabs.length"
        class="w-full h-full flex items-center justify-center opacity-50 flex-col gap-3"
      >
        <i class="fa-regular fa-folder-open text-3xl"></i>
        <span class="text-sm">Select a file to view</span>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: 'TabManager',
  // Let the parent react when a file is opened or when the last one is closed
  emits: ['tab-open', 'tabs-empty'],
  data() {
    return {
      tabs: [],
      activeTabId: null,
      nextTabId: 0
    }
  },
  computed: {
    activeTab() {
      return this.tabs.find(t => t.id === this.activeTabId)
    },
    tabCount() {
      return this.tabs.length
    }
  },
  methods: {
    addTab(file) {
      const tabId = `tab-${this.nextTabId++}`
      const tab = {
        id: tabId,
        name: file.name,
        path: file.path,
        openedAt: new Date()
      }
      this.tabs.push(tab)
      this.setActiveTab(tabId)
      this.$emit('tab-open', tab)
    },
    closeTab(tabId) {
      const index = this.tabs.findIndex(t => t.id === tabId)
      if (index === -1) return

      this.tabs.splice(index, 1)

      // Switch to adjacent tab or clear active tab
      if (this.activeTabId === tabId) {
        if (this.tabs.length > 0) {
          const nextIndex = index < this.tabs.length ? index : index - 1
          this.setActiveTab(this.tabs[nextIndex].id)
        } else {
          this.activeTabId = null
        }
      }

      // Notify when no file is left open (mobile: show the tree again)
      if (this.tabs.length === 0) {
        this.$emit('tabs-empty')
      }
    },
    closeAllTabs() {
      this.tabs = []
      this.activeTabId = null
      this.$emit('tabs-empty')
    },
    setActiveTab(tabId) {
      this.activeTabId = tabId
    },
    getTab(tabId) {
      return this.tabs.find(t => t.id === tabId)
    },
    getAllTabs() {
      return this.tabs
    },
    hasTab(path) {
      return this.tabs.some(t => t.path === path)
    }
  },
  expose: [
    'addTab',
    'closeTab',
    'closeAllTabs',
    'setActiveTab',
    'getTab',
    'getAllTabs',
    'hasTab'
  ]
}
</script>
